#include <cuda_runtime.h>
#include <cstdio>
#include <cstdint>
#include <cstring>
#include <vector>
#include <string>
#include <algorithm>
#define main historical_main
#include "../bsearch-cuda/main.cu"
#undef main
#define CHECK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(7);}}while(0)
constexpr uint64_t GUARD=0xD15EA5E5A55A77CCULL;constexpr int STRIDE=528,PATHS=72;static_assert(sizeof(size_t)==8);
struct InputCase{void*a;void*z;size_t n;bool fp64;};
int main(){int sizes[]={2,3,8,9,17,32,33,257,1025};std::vector<uint64_t>prefix(11988);FILE*f=fopen("/home/imo/HeCBench_julia/src/bsearch-julia/fixture.bin","rb");if(!f||fread(prefix.data(),8,prefix.size(),f)!=prefix.size())return 4;fclose(f);std::vector<InputCase>cases;std::vector<uint64_t>expected(STRIDE*PATHS,GUARD);size_t offset=0;int ci=0;
for(int fp64=0;fp64<2;fp64++)for(int sz:sizes){std::vector<double>a(sz),z(512);for(int i=0;i<sz+512;i++){double x;if(fp64){uint64_t b=prefix[offset+i];memcpy(&x,&b,8);}else{uint32_t b=uint32_t(prefix[offset+i]);float y;memcpy(&y,&b,4);x=y;}if(i<sz)a[i]=x;else z[i-sz]=x;}InputCase c;c.n=sz-1;c.fp64=fp64;size_t bytes=fp64?8:4;CHECK(cudaMalloc(&c.a,sz*bytes));CHECK(cudaMalloc(&c.z,512*bytes));if(fp64){CHECK(cudaMemcpy(c.a,a.data(),sz*8,cudaMemcpyHostToDevice));CHECK(cudaMemcpy(c.z,z.data(),512*8,cudaMemcpyHostToDevice));}else{std::vector<float>af(a.begin(),a.end()),zf(z.begin(),z.end());CHECK(cudaMemcpy(c.a,af.data(),sz*4,cudaMemcpyHostToDevice));CHECK(cudaMemcpy(c.z,zf.data(),512*4,cudaMemcpyHostToDevice));}for(int mode=0;mode<4;mode++)for(int j=0;j<512;j++){size_t idx=std::upper_bound(a.begin(),a.end(),z[j])-a.begin()-1;if(!(idx<size_t(sz-1)&&a[idx]<=z[j]&&z[j]<a[idx+1]))return 6;expected[((ci*4+mode)*STRIDE)+8+j]=idx;}cases.push_back(c);offset+=sz+512;ci++;}if(offset!=prefix.size())return 5;
size_t*out;CHECK(cudaMalloc(&out,expected.size()*8));auto launch=[&](){for(int i=0;i<18;i++)for(int mode=0;mode<4;mode++){auto c=cases[i];size_t*r=out+(i*4+mode)*STRIDE+8;if(c.fp64){auto a=(double*)c.a;auto z=(double*)c.z;if(mode==0)kernel_BS<<<2,256>>>(a,z,r,512,c.n);else if(mode==1)kernel_BS2<<<2,256>>>(a,z,r,512,c.n);else if(mode==2)kernel_BS3<<<2,256>>>(a,z,r,512,c.n);else kernel_BS4<<<2,256>>>(a,z,r,512,c.n);}else{auto a=(float*)c.a;auto z=(float*)c.z;if(mode==0)kernel_BS<<<2,256>>>(a,z,r,512,c.n);else if(mode==1)kernel_BS2<<<2,256>>>(a,z,r,512,c.n);else if(mode==2)kernel_BS3<<<2,256>>>(a,z,r,512,c.n);else kernel_BS4<<<2,256>>>(a,z,r,512,c.n);}}};std::vector<uint64_t>got(expected.size(),GUARD);CHECK(cudaMemcpy(out,got.data(),got.size()*8,cudaMemcpyHostToDevice));launch();CHECK(cudaDeviceSynchronize());
for(int trial=1;trial<=5;trial++){std::fill(got.begin(),got.end(),GUARD);CHECK(cudaMemcpy(out,got.data(),got.size()*8,cudaMemcpyHostToDevice));CHECK(cudaDeviceSynchronize());auto t=std::chrono::steady_clock::now();for(int rep=0;rep<5;rep++)launch();CHECK(cudaDeviceSynchronize());double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/5;CHECK(cudaMemcpy(got.data(),out,got.size()*8,cudaMemcpyDeviceToHost));bool ok=got==expected;size_t bad=0;for(size_t i=0;i<got.size();i++)bad+=got[i]!=expected[i];std::vector<uint64_t>art=prefix;art.insert(art.end(),got.begin(),got.end());const char*dir=getenv("STUDY_OUTPUT_DIR");std::string file=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*f=fopen(file.c_str(),"wb");fwrite(art.data(),8,art.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":38016,\"max_abs_error\":%zu,\"max_rel_error\":0,\"timing_region\":\"complete72path_binarysearch_suite_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":5,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint64\",\"count\":50004,\"byte_order\":\"little\"}}\n",trial,sec,ok?"true":"false",bad,file.c_str());}for(auto c:cases){cudaFree(c.a);cudaFree(c.z);}cudaFree(out);}
